pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(bool _payRoyalties) public {
        // The fuzzer provides the boolean argument for payRoyalties
        // We assume that _payRoyalties can be either true or false (this is already all possible values)

        // Call initialize with all fixed, valid dummy parameters except for payRoyalties
        c.initialize(
            address(0),          // _baseToken
            address(1),          // _nft
            100,                 // _virtualBaseTokenReserves
            100,                 // _virtualNftReserves
            0,                   // _changeFee
            0,                   // _feeRate
            bytes32(0),          // _merkleRoot
            false,               // _useStolenNftOracle
            _payRoyalties        // fuzzed _payRoyalties
        );

        // The general rule: payRoyalties() must equal the input _payRoyalties
        // The mutant omits the assignment, so payRoyalties remains false regardless of input
        assertTrue(c.payRoyalties() == _payRoyalties);
    }
}

